function m15ShowBrief() {
    m2InjectStyle();
    let b = document.getElementById('m2Brief'); if (!b) { b = document.createElement('div'); b.id = 'm2Brief'; document.body.appendChild(b); }
    b.innerHTML = '<div class="bSheet"><div class="bTape"><span>1st TANK BATTALION · OPERATION ICEBERG</span><span>PACIFIC 03</span></div><div class="bBody">' +
        '<h2>THE LOST PATROL</h2><p class="bText" id="m15Typed"></p>' +
        '<ul><li>You command <b>C-12</b>, an M4A3 Sherman, with <b>Charlie 7, 9 and 11</b> alongside you.</li>' +
        '<li><b>1. Get there:</b> the bamboo is too thick for tanks, so stick to the <b>trails</b>. It is a long way north: take the centre trail over the <b>plank bridge</b>, or loop round the east or west glades, to reach the <b>old shrine</b>. Japanese tanks are dug in all along the way.</li>' +
        '<li><b>2. Hold the shrine:</b> stay close to the patrol while they climb aboard (watch the gauge). Infantry will charge out of the bamboo, so run them down or shoot them, and Ha-Go and Chi-Ha tanks will come down the trails.</li>' +
        '<li><b>3. Beat the counter-attack:</b> once everyone is aboard, a Japanese tank column hits the shrine. Knock out every tank before you leave.</li>' +
        '<li><b>4. Bring them home:</b> drive all the way back south to the <b>aid station</b> through the ambushes. If a tank carrying Marines is knocked out, they go down with it.</li>' +
        '<li>Fording the <b>stream</b> slows you down. Press <b>R</b> to repair. Bring all six home, with half your armour left, for three stars.</li></ul>' +
        '<div class="bNote">W A S D drive · mouse aim · click / space fire · R repair. The map scrolls: watch the minimap and the arrow. The bamboo canopy opens up around your tank.</div>' +
        '<button class="bGo" id="m15Go">MOUNT UP ▶</button></div></div>';
    b.hidden = false; b.style.display = '';
    const txt = 'May 1945. Okinawa. North of Wana the hills are thick with giant bamboo, cut only by narrow trails. A patrol of the 7th Marines went in to scout them and was ambushed. Six men, two of them wounded, are holding out at an old shrine with a dying radio. The infantry cannot reach them. The tanks can.';
    const el = document.getElementById('m15Typed'); let i = 0; const iv = setInterval(function () { i += 2; el.textContent = txt.slice(0, i); if (i >= txt.length) clearInterval(iv); }, 20);
    // paint the forest while the crew reads the brief, so the battle starts without a stall
    setTimeout(function () { try { const W = M15W, H = M15H, key = W + 'x' + H; if (M15.artKey !== key) { M15.art = m15BuildArt(W, H); M15.artKey = key; M15.canopy = m15BuildCanopy(W, H); M15.canopyKey = key; } } catch (e) {} }, 400);
    document.getElementById('m15Go').onclick = function () { clearInterval(iv); b.hidden = true; try { playTone(520, 760, .1, .05, 'triangle'); } catch (e) {} startCampaignMission(); };
}
